from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}


def _valid_tier(tier):
    return tier in TIER_FEES


def _valid_amount(amount):
    return isinstance(amount, int) and amount > 0


def _valid_method(method):
    return method == "card" or method == "transfer"


def _build_receipt(member_id, method, status_word, fee):
    return method + ":" + member_id + ":" + status_word + ":" + str(fee)


def _validate_tier_payment(member, payment):
    """Shared gate for tier, amount and method checks across all statuses."""
    if not _valid_tier(member["tier"]):
        return "unknown tier"
    if not _valid_amount(payment["amount"]):
        return "bad amount"
    if not _valid_method(payment["method"]):
        return "unsupported method"
    return None


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}

    if status == "active":
        failure = _validate_tier_payment(member, payment)
        if failure is not None:
            return {"ok": False, "error": failure}
        fee = TIER_FEES[member["tier"]]
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return {
            "ok": True,
            "status": "renewed",
            "fee": fee,
            "receipt": _build_receipt(member["id"], payment["method"], "renewed", fee),
        }

    if status == "lapsed":
        if not _valid_tier(member["tier"]):
            return {"ok": False, "error": "unknown tier"}
        if (
            "expired_days" not in member
            or not isinstance(member["expired_days"], int)
            or member["expired_days"] < 0
        ):
            return {"ok": False, "error": "bad expiry"}
        failure = _validate_tier_payment(member, payment)
        if failure is not None:
            return {"ok": False, "error": failure}
        if member["expired_days"] <= GRACE_DAYS:
            fee = TIER_FEES[member["tier"]] + LATE_FEE
            status_word = "renewed"
        else:
            fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
            status_word = "reinstated"
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return {
            "ok": True,
            "status": status_word,
            "fee": fee,
            "receipt": _build_receipt(member["id"], payment["method"], status_word, fee),
        }

    if status == "suspended":
        if not _valid_tier(member["tier"]):
            return {"ok": False, "error": "unknown tier"}
        if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
            return {"ok": False, "error": "bad strikes"}
        if member["strikes"] >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}
        failure = _validate_tier_payment(member, payment)
        if failure is not None:
            return {"ok": False, "error": failure}
        fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return {
            "ok": True,
            "status": "reactivated",
            "fee": fee,
            "receipt": _build_receipt(member["id"], payment["method"], "reactivated", fee),
        }

    return {"ok": False, "error": "unknown status"}

